import type { Run, Spec, Step } from './types'

// The routine as an automatic flow graph (n8n style), drawn from the recipe alone: trigger →
// one node per condition → one node per step, with the fixed guard as a side path off the step
// that sends. Counters come from the latest run (a test run shows a "Test run" tag).

const REFUSED = 'Needs you, it costs money or changes the plan'

interface Counts { matched: number; byStep: Map<string, string>; guard: number }

function count(spec: Spec, run?: Run): Counts | null {
  if (!run || !run.ok) return null
  const did = run.did ?? []
  const byStep = new Map<string, string>()
  const sent = did.filter((d) => d.do === 'carry_out').length
  const refused = did.filter((d) => d.do === 'notify' && (d.text ?? '').startsWith(REFUSED)).length
  const told = did.filter((d) => d.do === 'notify' && !(d.text ?? '').startsWith(REFUSED))
  const sendTexts = spec.then.filter((s) => s.do === 'carry_out').map((s) => s.text)
  const noted = (run.log ?? []).filter((l) => l && !sendTexts.some((t) => l.startsWith(t))).length
  for (const s of spec.then) {
    if (s.do === 'carry_out' && sent) byStep.set(s.id, `${sent} sent`)
    if (s.do === 'notify') {
      const n = told.filter((d) => d.channel === (s.channel ?? 'both')).length
      if (n) byStep.set(s.id, `${n} told`)
    }
    if (s.do === 'log' && noted) byStep.set(s.id, `${noted} noted`)
  }
  const handled = typeof run.result === 'number' ? run.result : new Set(did.map((d) => d.card)).size
  return { matched: handled, byStep, guard: refused }
}

function stepTitle(s: Step): string {
  if (s.do === 'carry_out') return 'Send the message'
  if (s.do === 'log') return 'Note it'
  return s.channel === 'phone' ? 'Tell you on your phone' : s.channel === 'teams' ? 'Tell you on Teams' : 'Tell you'
}

function Node({
  icon, tone, title, text, badge, active, dashed,
}: { icon: ReactNode; tone: string; title: string; text: string; badge?: string; active?: boolean; dashed?: boolean }) {
  return (
    <div
      className={cn(
        'relative w-full min-w-0 shrink-0 rounded-xl border bg-white p-2.5 shadow-[0_1px_2px_rgba(15,23,42,0.04)] lg:w-[200px]',
        dashed ? 'border-dashed border-ink-3/40 bg-panel' : 'border-line',
        active && 'ring-2 ring-emerald-500/35',
      )}
      title={text}
    >
      <div className="flex items-start gap-2.5">
        <div className={cn('grid h-8 w-8 shrink-0 place-items-center rounded-lg', tone)}>{icon}</div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center justify-between gap-1.5">
            <div className="truncate text-[13px] font-semibold text-ink">{title}</div>
            {badge && (
              <span className="shrink-0 rounded-full bg-emerald-50 px-1.5 py-px text-[11px] font-semibold text-emerald-700 ring-1 ring-emerald-600/20">
                {badge}
              </span>
            )}
          </div>
          <div className="mt-0.5 line-clamp-2 text-[12.5px] leading-snug text-ink-2">{text}</div>
        </div>
      </div>
    </div>
  )
}

/** A thin line with a small arrow: down in the vertical layout, right in the wide one. */
function Arrow({ wide, dashed, side }: { wide?: boolean; dashed?: boolean; side?: boolean }) {
  const stroke = { stroke: 'currentColor', strokeWidth: 1.25, fill: 'none', strokeDasharray: dashed ? '3 3' : undefined }
  const down = (
    <svg width="10" height="22" viewBox="0 0 10 22" aria-hidden><line x1="5" y1="0" x2="5" y2="20" {...stroke} /><path d="M1.5 16 L5 21 L8.5 16" {...stroke} strokeDasharray={undefined} /></svg>
  )
  const right = (
    <svg width="28" height="10" viewBox="0 0 28 10" aria-hidden><line x1="0" y1="5" x2="26" y2="5" {...stroke} /><path d="M22 1.5 L27 5 L22 8.5" {...stroke} strokeDasharray={undefined} /></svg>
  )
  // Main path: down when narrow, right when wide. Side path: the opposite direction.
  const horizontalHere = side ? !wide : !!wide
  if (!wide) return <div className={cn('shrink-0 text-ink-3/60', side ? 'mt-[11px]' : 'ml-[26px]')}>{horizontalHere ? right : down}</div>
  return (
    <div className="shrink-0 text-ink-3/60">
      <div className={cn(side ? 'ml-[26px] lg:hidden' : 'ml-[26px] lg:hidden')}>{side ? right : down}</div>
      <div className={cn('hidden lg:block', side ? 'ml-[26px]' : 'mt-[17px]')}>{side ? down : right}</div>
    </div>
  )
}

export function FlowGraph({ spec, run, wide }: { spec: Spec; run?: Run; wide?: boolean }) {
  const c = count(spec, run)
  const sendAt = spec.then.findIndex((s) => s.do === 'carry_out')
  const guard = (
    <Node
      dashed
      icon={<Lock size={15} className="text-ink-2" />}
      tone="bg-white ring-1 ring-line"
      title="You decide"
      text="Costs money or changes the plan → it comes to you"
      badge={c?.guard ? `${c.guard} to you` : undefined}
      active={!!c?.guard}
    />
  )
  // Main path direction per layout; a step that sends carries the guard as a side branch.
  const main = wide ? 'flex flex-col lg:flex-row lg:items-start' : 'flex flex-col'
  const slot = wide ? 'flex flex-row lg:flex-col' : 'flex flex-row'
  const nodes: ReactNode[] = [
    <Node
      key="trigger"
      icon={<Radar size={15} className="text-ok" />}
      tone="bg-ok/10"
      title="Every portal check"
      text="New files, replies and open decisions, about every minute"
    />,
    ...spec.when.map((cond, i) => (
      <Node
        key={cond.id}
        icon={<Filter size={15} className="text-amber-700" />}
        tone="bg-amber-50"
        title={i === 0 ? 'If' : 'And'}
        text={cond.text}
        badge={i === spec.when.length - 1 && c ? `${c.matched} matched` : undefined}
        active={i === spec.when.length - 1 && !!c?.matched}
      />
    )),
    ...spec.then.map((s, i) => {
      const badge = c?.byStep.get(s.id)
      const node = (
        <Node
          key={s.id}
          icon={<StepIcon step={s} size={15} />}
          tone={s.do === 'log' ? 'bg-panel ring-1 ring-line' : 'bg-ok/10'}
          title={stepTitle(s)}
          text={s.text}
          badge={badge}
          active={!!badge}
        />
      )
      if (i !== sendAt) return node
      return (
        <div key={s.id} className={cn(slot, 'min-w-0 items-start gap-0')}>
          <div className="min-w-0 flex-1 lg:flex-none">{node}</div>
          <Arrow wide={wide} side dashed />
          <div className="min-w-0 flex-1 lg:flex-none">{guard}</div>
        </div>
      )
    }),
  ]
  if (sendAt < 0) nodes.push(<div key="guard" className="opacity-90">{guard}</div>)

  return (
    <div className="relative">
      {run?.dry && (
        <span className="absolute right-0 top-0 z-10 rounded-full bg-panel px-2 py-0.5 text-[11px] font-semibold text-ink-3 ring-1 ring-line">
          Test run
        </span>
      )}
      <div className={cn(main, wide && 'lg:overflow-x-auto lg:pb-2')}>
        {nodes.map((n, i) => (
          <div key={i} className={cn('flex min-w-0', wide ? 'flex-col lg:flex-row lg:items-start' : 'flex-col')}>
            {i > 0 && <Arrow wide={wide} dashed={i === nodes.length - 1 && sendAt < 0} />}
            <div className={cn(wide ? 'lg:w-auto' : 'max-w-[400px]')}>{n}</div>
          </div>
        ))}
      </div>
    </div>
  )
}

