          title={stepTitle(s)}
          text={s.text}
          badge={badge}
          active={!!badge}
        />
      )
      if (i !== sendAt) return { key: s.id, node }
      return {
        key: s.id,
        node: (
          <div className={cn('flex flex-row items-start', wide && 'lg:flex-col')}>
            <div className={cn('min-w-0 flex-[3]', wide && 'lg:flex-none')}>{node}</div>
            <Arrow wide={wide} side dashed />
            <div className={cn('min-w-0 flex-[2]', wide && 'lg:flex-none')}>{guard}</div>
          </div>
        ),
      }
    }),
  ]
  if (sendAt < 0) columns.push({ key: 'guard', node: guard })

  return (
    <div className="relative">
      {run?.dry && (
        <span className="absolute right-0 top-0 z-10 rounded-full bg-white px-2 py-0.5 text-[11px] font-semibold text-ink-3 ring-1 ring-line">
          Test run
        </span>
      )}
      <div className={cn('flex flex-col', wide && 'lg:flex-row lg:items-start lg:overflow-x-auto lg:pb-2')}>
        {columns.map((col, i) => (
          <div key={col.key} className={cn('flex min-w-0 flex-col', wide && 'lg:flex-row lg:items-start')}>
            {i > 0 && <Arrow wide={wide} dashed={col.key === 'guard'} />}
            {col.node}
          </div>
        ))}
      </div>
    </div>
  )
}
